function Motif({ kind, T }) {
  const line = { stroke: T.glow, fill: "none", strokeLinecap: "round", strokeLinejoin: "round" };
  if (kind === "bolt")
    return (
      <g {...line} strokeWidth="2" opacity="0.9">
        <path d="M162 38l-12 20h11l-9 20 20-23h-11z" fill={T.glow} stroke="none" />
        <path d="M132 44l-7 14M190 44l7 14M120 66l-11 6M200 66l11 6" strokeWidth="1.4" opacity="0.6" />
      </g>
    );
  if (kind === "wave" || kind === "tide")
    return (
      <g {...line} strokeWidth="1.7" opacity="0.85">
        <path d="M128 54c8-7 16-7 24 0s16 7 24 0 16-7 24 0" />
        <path d="M124 66c8-7 16-7 24 0s16 7 24 0 16-7 24 0" opacity="0.7" />
        <path d="M132 78c8-7 16-7 24 0s16 7 24 0" opacity="0.45" />
      </g>
    );
  if (kind === "stone")
    return (
      <g opacity="0.9">
        <path d="M148 44l16-6 16 10-6 18-18 4-12-14z" fill={T.glow} opacity="0.35" />
        <path d="M148 44l16-6 16 10-6 18-18 4-12-14z" {...line} strokeWidth="1.6" />
        <path d="M134 72l10-4 6 8-8 6z" {...line} strokeWidth="1.3" opacity="0.6" />
        <path d="M186 70l10 4-4 9-9-5z" {...line} strokeWidth="1.3" opacity="0.6" />
      </g>
    );
  if (kind === "flame")
    return (
      <g opacity="0.9">
        <path d="M160 34c9 12 14 18 14 27a14 14 0 01-28 0c0-9 5-15 14-27z" fill={T.glow} opacity="0.5" />
        <path d="M160 34c9 12 14 18 14 27a14 14 0 01-28 0c0-9 5-15 14-27z" {...line} strokeWidth="1.6" />
        <path d="M136 60c5 7 8 10 8 15a8 8 0 01-16 0c0-5 3-8 8-15z" {...line} strokeWidth="1.3" opacity="0.55" />
        <path d="M184 60c5 7 8 10 8 15a8 8 0 01-16 0c0-5 3-8 8-15z" {...line} strokeWidth="1.3" opacity="0.55" />
      </g>
    );
  if (kind === "sun")
    return (
      <g {...line} strokeWidth="1.6" opacity="0.9">
        <circle cx="160" cy="60" r="14" />
        <path d="M160 36v-8M160 92v-8M136 60h-8M192 60h-8M143 43l-6-6M177 43l6-6M143 77l-6 6M177 77l6 6" />
      </g>
    );
  if (kind === "vine")
    return (
      <g {...line} strokeWidth="1.6" opacity="0.9">
        <path d="M160 88c0-14-12-18-12-30s10-14 10-22" />
        <path d="M160 70c8-4 18-2 22-10" />
        <path d="M158 56c-8-4-18-2-22-10" />
        <ellipse cx="186" cy="58" rx="6" ry="3.4" transform="rotate(-25 186 58)" fill={T.glow} stroke="none" opacity="0.7" />
        <ellipse cx="132" cy="44" rx="6" ry="3.4" transform="rotate(25 132 44)" fill={T.glow} stroke="none" opacity="0.7" />
      </g>
    );
  if (kind === "moon")
    return (
      <g opacity="0.95">
        <path d="M170 40a20 20 0 10 0 40 24 24 0 010-40z" fill={T.glow} opacity="0.55" />
        <path d="M170 40a20 20 0 10 0 40 24 24 0 010-40z" stroke={T.glow} strokeWidth="1.5" fill="none" />
        <g fill={T.glow} opacity="0.8">
          <circle cx="128" cy="48" r="1.8" />
          <circle cx="140" cy="72" r="1.4" />
          <circle cx="198" cy="52" r="1.6" />
          <circle cx="206" cy="76" r="1.2" />
        </g>
      </g>
    );
  return (
    <g stroke={T.glow} strokeWidth="1.6" fill="none" opacity="0.85" strokeLinecap="round">
      <path d="M160 44a18 18 0 1 0 18 18 13 13 0 0 0-13-13 8.5 8.5 0 0 0-8.5 8.5 4.5 4.5 0 0 0 4.5 4.5" />
    </g>
  );
}

