function HexButton({ label, tone, onPress }) {
  const T = useT();
  const fill = tone === "minus" ? RED : BLUE;
  const shade = tone === "minus" ? RED_DARK : BLUE_DARK;
  return (
    <button
      onClick={onPress}
      className="si-press relative w-full select-none focus:outline-none"
      style={{ aspectRatio: "1.8 / 1" }}
      aria-label={label}
    >
      <div className="absolute inset-0" style={{ background: T.gold, clipPath: HEX }} />
      <div
        className="absolute"
        style={{
          inset: "3px",
          clipPath: HEX,
          background: `linear-gradient(160deg, ${fill} 0%, ${fill} 55%, ${shade} 100%)`,
        }}
      />
      <span
        className="relative text-white"
        style={{
          fontFamily: numFont,
          fontWeight: 700,
          fontSize: "clamp(20px, 6vw, 30px)",
          textShadow: "0 2px 4px rgba(0,0,0,.45)",
        }}
      >
        {label}
      </span>
    </button>
  );
}

function Chip({ label, active, color, onPress, small }) {
  const T = useT();
  return (
    <button
      onClick={onPress}
      className="si-press rounded-full"
      style={{
        fontFamily: jaFont,
        fontSize: small ? 12 : 13,
        padding: small ? "5px 10px" : "7px 13px",
        color: active ? "#20180E" : "#CFE0D6",
        background: active ? color || T.parch : "rgba(233,216,166,.07)",
        border: `1px solid ${active ? color || T.parch : "rgba(201,164,104,.4)"}`,
      }}
    >
      {label}
    </button>
  );
}

